    public static readonly IReadOnlyList<ScriptBuildToken> StasV3Tokens;

    public static IReadOnlyList<ScriptBuildToken> DstasTokens { get; private set; }
    public static IReadOnlyList<ScriptBuildToken> DstasBaseTokens { get; private set; }

    private static void InitDstasTokens()
    {
        var allTokens = SimpleScriptReader.Read(DummyDstasScript, Network.Mainnet);

        // Token[0] = owner (20-byte PKH), Token[1] = actionData (OP_0)
        allTokens[0].IsReceiverId = true;
        allTokens[1].IsActionData = true;

        // Find redemption and flags in the tail (after OP_RETURN marker 0x6a)
        // The DSTAS script ends with: OP_RETURN <redemption 20 bytes> <flags 1 byte>
        // In the hex, the last tokens are: 6a 14 2222...2222 01 00
        var tokenCount = allTokens.Count;
        if (tokenCount >= 3)
        {
            // flags is the last token, redemption is second-to-last, OP_RETURN is third-to-last
            allTokens[tokenCount - 2].IsRedemptionId = true;
            allTokens[tokenCount - 1].IsFlagsField = true;
        }

        // Extract base tokens (everything between actionData and OP_RETURN tail)
        // Base starts at index 2 and goes until the OP_RETURN marker
        var baseTokensList = new System.Collections.Generic.List<ScriptBuildToken>();
        for (var i = 2; i < tokenCount; i++)
        {
            var token = allTokens[i];
            if (token.OpCode == OpCode.OP_RETURN)
                break;
            baseTokensList.Add(token);
        }

        DstasTokens = allTokens;
        DstasBaseTokens = baseTokensList;
    }

