        new((byte)OpCode.OP_DUP),
        new((byte)OpCode.OP_HASH160),
        new(20, 20, true),
        new((byte)OpCode.OP_EQUALVERIFY),
        new((byte)OpCode.OP_CHECKSIGVERIFY),
